def diagnose_port_exhaustion(tw_sockets: int, port_cap: int = 28232, eaddrnotavail_pct: float = 0.0) -> str:
    if tw_sockets >= int(port_cap * 0.90) and eaddrnotavail_pct > 0.0:
        return 'EPHEMERAL_PORT_EXHAUSTION_TIME_WAIT_STORM'
    return 'CHECK_OTHER_UPSTREAM_FAILURE'

