def validate_port_range(low: int, high: int, reserved: list[int]) -> int:
    if low < 1024 or high > 65535 or low >= high:
        raise ValueError('Port range must lie within [1024, 65535]')
    reserved_in_range = sum(1 for p in set(reserved) if low <= p <= high)
    return (high - low + 1) - reserved_in_range

def min_snat_ips_needed(target_concurrent_conns: int, ports_per_ip: int = 64511, headroom: float = 1.25) -> int:
    if target_concurrent_conns <= 0:
        raise ValueError('target_concurrent_conns must be positive')
    import math
    return math.ceil((target_concurrent_conns * headroom) / ports_per_ip)

def conntrack_ram_mb(max_entries: int, bytes_per_entry: int = 320) -> float:
    if max_entries <= 0:
        raise ValueError('max_entries must be positive')
    return round((max_entries * bytes_per_entry) / 1e6, 2)

def is_idempotent_retry_safe(http_method: str, bytes_sent_to_upstream: int) -> bool:
    if bytes_sent_to_upstream == 0:
        return True
    return http_method.upper() in {'GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE'}

def verify_soak_test(rps: int, tw_sockets: int, new_conns_per_sec: int, eaddr_errors: int) -> bool:
    if eaddr_errors > 0:
        return False
    if tw_sockets >= 500:
        return False
    return (new_conns_per_sec / max(1, rps)) < 0.01
